    {
      "name": "test_length_matches_n",
      "source": "def test_length_matches_n(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    pattern = lines[1]
    answer = run(x).strip()
    # This is stricter than exact_length: it also checks pattern length equals n (given by problem).
    assert len(pattern) == n
    assert len(answer) == len(pattern)"
    },
    {
      "name": "test_no_other_pokemon_fits",
      "source": "def test_no_other_pokemon_fits(run, x):
    pokemon = ['vaporeon', 'jolteon', 'flareon', 'espeon', 'umbreon', 'leafeon', 'glaceon', 'sylveon']
    lines = x.strip().split('\n')
    n = int(lines[0])
    pattern = lines[1]
    answer = run(x).strip()
    matches = []
    for p in pokemon:
        if len(p) == n:
            ok = True
            for i, ch in enumerate(pattern):
