    },
    {
      "name": "test_correctness_via_verification",
      "source": "def test_correctness_via_verification(run, x):
    pokemon = ['vaporeon', 'jolteon', 'flareon', 'espeon', 'umbreon', 'leafeon', 'glaceon', 'sylveon']
    lines = x.strip().split('\n')
    n = int(lines[0])
    pattern = lines[1]
    answer = run(x).strip()
    # Verify answer matches pattern and is among Pokémon of length n.
    candidates = [p for p in pokemon if len(p) == n]
    assert answer in candidates, f'Answer {answer} not a Pokémon of length {n}'
    for i, ch in enumerate(pattern):
        if ch != '.' and answer[i] != ch:
