tests_src:
def test_non_negative_integer(run, x):
    out = run(x).strip()
    assert out.isdigit() or (out[0] == '-' and out[1:].isdigit())
    val = int(out)
    assert val >= 0

def test_upper_bound(run, x):
    # maximum possible positions: 4 directions for each cell that is empty
    # but also each must have at least one actor in that direction.
    # A trivial bound: 4 * n * m
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    out = int(run(x).strip())
    assert out <= 4 * n * m

def test_metamorphic_rotate_180(run, x):
    # Rotating the grid 180 degrees (reverse rows, reverse each row) should give same answer
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [list(map(int, lines[i+1].split())) for i in range(n)]
    # Build rotated grid: reverse rows, reverse each row
    rotated_grid = [row[::-1] for row in grid[::-1]]
    # Construct input string
    rotated_input = f'{n} {m}\n' + '\n'.join(' '.join(map(str, row)) for row in rotated_grid) + '\n'
    out1 = int(run(x).strip())
    out2 = int(run(rotated_input).strip())
    assert out1 == out2

def test_certificate_each_position_empty_cell(run, x):
    # Verify that for each counted position, the cell is empty.
    # We'll recompute the answer from the output and then check a sample? Not possible.
    # Instead, we can compute the set of positions that are good according to definition,
    # and compare count. That's a full verification; but inputs are small enough.
