def test_consecutive_pairs_match_input(run, x):
    lines = x.strip().split('\n')[1:]
    front_of = {}
    back_of = {}
    for line in lines:
        a, b = map(int, line.split())
        if a != 0:
            back_of[a] = b  # a's back is b
        if b != 0:
            front_of[b] = a  # b's front is a
    out = list(map(int, run(x).strip().split()))
    for i in range(len(out)-1):
        cur = out[i]
