        if nxt in front_of:
            assert front_of[nxt] == cur, f'Pair ({cur},{nxt}) violates front relation'
        else:
            assert cur == 0, f'Unexpected non‑zero predecessor for {nxt}'
    # Also check that the first's front is 0 and last's back is 0 already covered
