    # The mapping a->b must be consistent with the sequence.
    lines = x.strip().split('\n')[1:]
    a_to_b = {}
    for line in lines:
        a, b = map(int, line.split())
        if a != 0:
            a_to_b[a] = b
    out = list(map(int, run(x).strip().split()))
    for i in range(len(out)-1):
        cur = out[i]
        if cur in a_to_b:
            assert a_to_b[cur] == out[i+1], f'Sequence breaks a->b mapping at index {i}'
    pass

