      "name": "test_equality_clusters_consistency",
      "source": "def test_equality_clusters_consistency(run, x):
    # If two dishes from the same set are forced equal via a third dish, they must have same value.
    out = run(x).strip('\n')
    lines = out.split('\n')
    if lines[0].strip() != 'Yes':
        return
    n, m = map(int, x.strip().split('\n')[0].split())
    a = x.strip().split('\n')[1:1+n]
    vals1 = list(map(int, lines[1].split()))
    vals2 = list(map(int, lines[2].split()))
    # Build equivalence graph on all dishes (0..n-1 first set, n..n+m-1 second set)
    adj = [[] for _ in range(n + m)]
    for i in range(n):
        for j in range(m):
            if a[i][j] == '=':
                adj[i].append(n + j)
                adj[n + j].append(i)
    # DFS to find connected components
    visited = [False] * (n + m)
    for start in range(n + m):
        if not visited[start]:
            stack = [start]
            comp = []
            while stack:
                u = stack.pop()
                if visited[u]:
                    continue
                visited[u] = True
                comp.append(u)
                for v in adj[u]:
                    if not visited[v]:
                        stack.append(v)
            # All dishes in the same component must have same value
            vals = [vals1[u] if u < n else vals2[u - n] for u in comp]
            assert len(set(vals)) == 1, f'Equality cluster {comp} has differing values {vals}'"
    },
