tests_src:
def test_output_is_positive_integer(run, x):
    out = run(x).strip()
    assert out.isdigit() and int(out) >= 1

def test_output_at_most_n(run, x):
    n = int(x.strip().split('\n')[0])
    out = int(run(x).strip())
    assert out <= n

def test_output_integer(run, x):
    out = run(x).strip()
    assert out.isdigit()

def test_all_equal_is_whole_sequence(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    vals = list(map(int, lines[1].split()))
    if len(set(vals)) == 1:
        out = int(run(x).strip())
        assert out == n

def test_two_element_input_output_two(run, x):
    n = int(x.strip().split('\n')[0])
    if n == 2:
        out = int(run(x).strip())
        assert out == 2

def test_alternating_two_values_is_whole(run, x):
    lines = x.strip().split('\n')
    vals = list(map(int, lines[1].split()))
    if len(vals) >= 2:
        # Check if sequence is exactly a, b, a, b, ... (alternating two distinct numbers)
        # This fits AAP with p = a, q = b - a
        a, b = vals[0], vals[1]
        ok = True
        for i, v in enumerate(vals):
            if i % 2 == 0:
                if v != a:
                    ok = False
                    break
            else:
                if v != b:
                    ok = False
                    break
        if ok and a != b:
            out = int(run(x).strip())
            assert out == len(vals)

def test_arithmetic_progression_is_whole(run, x):
    lines = x.strip().split('\n')
    vals = list(map(int, lines[1].split()))
    if len(vals) >= 2:
        d = vals[1] - vals[0]
        ok = True
        for i in range(1, len(vals)):
            if vals[i] - vals[i-1] != d:
                ok = False
                break
        if ok:
            # An arithmetic progression is also an AAP (with q = d for even indices, but formula works)
            out = int(run(x).strip())
            assert out == len(vals)

def test_sequence_follows_AAP_formula_is_whole(run, x):
    lines = x.strip().split('\n')
    vals = list(map(int, lines[1].split()))
    if len(vals) >= 2:
        p = vals[0]
        # Determine q from first two elements: a2 = p + q => q = vals[1] - p
        q = vals[1] - p
        ok = True
        for i in range(1, len(vals)):
            expected = vals[i-1] + ((-1)**(i+1)) * q
            if vals[i] != expected:
                ok = False
                break
        if ok:
            out = int(run(x).strip())
            assert out == len(vals)

def test_single_element_input_output_one(run, x):
    n = int(x.strip().split('\n')[0])
    if n == 1:
        out = int(run(x).strip())
        assert out == 1

def test_output_non_decreasing_when_duplicating_input(run, x):
    # Metamorphic relation: If we duplicate the sequence, the longest AAP subsequence
    # length should not decrease (because we can still pick the same subsequence as before).
    lines = x.strip().split('\n')
    n = int(lines[0])
    vals = lines[1].split()
    # Build duplicated input: n*2 followed by vals repeated
    dup_input = f'{2*n}\n{' '.join(vals + vals)}'
    out_orig = int(run(x).strip())
    out_dup = int(run(dup_input).strip())
    assert out_dup >= out_orig

def test_non_negative(run, x):
    out = run(x).strip()
    assert out.isdigit() or (out[0]=='-' and out[1:].isdigit()), f'Output not integer: {out}'
    val = int(out)
    assert val >= 0, f'Output negative: {val}'

def test_integer(run, x):
    out = run(x).strip()
    assert out.isdigit() or (out[0]=='-' and out[1:].isdigit()), f'Output not integer: {out}'

def test_upper_bound_total_vv_pairs_squared(run, x):
    s = x.strip()
    total_vv = 0
    for i in range(len(s)-1):
        if s[i]=='v' and s[i+1]=='v':
            total_vv += 1
    bound = total_vv * total_vv  # each wow uses two distinct vv pairs
    out = int(run(x).strip())
    assert out <= bound, f'Output {out} exceeds bound {bound}'

def test_reversal_invariance(run, x):
    s = x.strip()
    rev = s[::-1]
    out1 = int(run(x).strip())
    out2 = int(run(rev + '\n').strip())
    assert out1 == out2, f'Reversal invariance failed: {out1} vs {out2}'

def test_small_brute(run, x):
    s = x.strip()
    if len(s) > 20:
        return  # skip for large inputs
    # brute force count of subsequences equal to "wow"
    n = len(s)
    cnt = 0
    for i in range(n):
        if s[i] != 'v':
            continue
        # look for consecutive vv as first w
        if i+1 < n and s[i+1] == 'v':
            # first w is positions i,i+1
            for j in range(i+2, n):
                if s[j] == 'o':
                    for k in range(j+1, n):
                        if s[k] == 'v' and k+1 < n and s[k+1] == 'v':
                            cnt += 1
    out = int(run(x).strip())
    assert out == cnt, f'Brute force mismatch: {out} vs {cnt}'

def test_remove_o_zero(run, x):
    s = x.strip()
    # remove all 'o's
    t = ''.join(ch for ch in s if ch == 'v')
    if t == s:
        return  # no 'o' removed, test not needed
    out = int(run(t + '\n').strip())
    assert out == 0, f'After removing all o, wow factor should be 0, got {out}'

def test_add_vv_non_decreasing(run, x):
    s = x.strip()
    # prepend "vv"
    t = 'vv' + s
    out_orig = int(run(x).strip())
    out_new = int(run(t + '\n').strip())
    assert out_new >= out_orig, f'Adding vv at start decreased wow factor: {out_orig} -> {out_new}'

def test_certificate_exact(run, x):
    s = x.strip()
    n = len(s)
    # compute prefix counts of 'vv' pairs
    pref = [0]*(n+1)
    for i in range(1, n):
        add = 1 if s[i-1]=='v' and s[i]=='v' else 0
        pref[i+1] = pref[i] + add
    # compute suffix counts
    suff = [0]*(n+2)
    for i in range(n-2, -1, -1):
        add = 1 if s[i]=='v' and s[i+1]=='v' else 0
        suff[i+1] = suff[i+2] + add
    ans = 0
    for i in range(n):
        if s[i] == 'o':
            left = pref[i]   # number of vv pairs ending before i
            right = suff[i+2]  # number of vv pairs starting after i
            ans += left * right
    out = int(run(x).strip())
    assert out == ans, f'Certificate mismatch: {out} vs {ans}'

def test_length_less_3_zero(run, x):
    s = x.strip()
    if len(s) < 3:
        out = int(run(x).strip())
        assert out == 0, f'Length <3 must give 0, got {out}'

def test_no_o_zero(run, x):
    s = x.strip()
    if 'o' not in s:
        out = int(run(x).strip())
        assert out == 0, f'No o must give 0, got {out}'

