    out = run(x)
    # Output should be a string, same length as s
    assert len(out.rstrip('\n')) == len(s), f'Output length {len(out)} vs input length {len(s)}'

def test_digits_unchanged(run, x):
    lines = x.strip('\n').split('\n')
    if len(lines) < 3:
        return
    s = lines[2]
    out = run(x).rstrip('\n')
    for i, ch in enumerate(s):
        if ch.isdigit():
            assert out[i] == ch, f'Digit at position {i} changed'

def test_non_english_letters_unchanged(run, x):
    lines = x.strip('\n').split('\n')
    if len(lines) < 3:
        return
    s = lines[2]
    out = run(x).rstrip('\n')
    for i, ch in enumerate(s):
        if not ('a' <= ch <= 'z' or 'A' <= ch <= 'Z' or '0' <= ch <= '9'):
            # Not English letter nor digit -> should be unchanged
            assert out[i] == ch, f'Non-English character at {i} changed'

def test_capitalization_preserved(run, x):
    lines = x.strip('\n').split('\n')
    if len(lines) < 3:
        return
    s1_layout = lines[0]
    s2_layout = lines[1]
    s = lines[2]
    out = run(x).rstrip('\n')
    for i, ch in enumerate(s):
        if 'a' <= ch <= 'z':
            # lowercase English letter -> output should be lowercase
            if 'a' <= out[i] <= 'z':
                continue  # okay
            # If output is uppercase, that's wrong unless mapping gave uppercase due to bug
            # Actually mapping should preserve case, so output[i] should be lowercase
            assert 'a' <= out[i] <= 'z', f'Lowercase input became uppercase at {i}'
        elif 'A' <= ch <= 'Z':
            # uppercase English letter -> output should be uppercase
            assert 'A' <= out[i] <= 'Z', f'Uppercase input became lowercase at {i}'

