    # Actually we don't know the pattern. Instead, we can test that result(n,m) is consistent with Fibonacci.
    # Let's test that result(n,m) equals result(m,n) (already covered) and that result(n,1) = 2 if n==1 else 2*n? Not correct.
    # Instead, use that for 1xm we computed via brute force earlier (test_1x_small_bruteforce).
    # This test will be a simple sanity: for n=3,m=3, we can brute force (3x3=9 cells, 2^9=512 possibilities, feasible).
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n == 3 and m == 3:
        import itertools
        total = 0
        for bits in itertools.product([0,1], repeat=9):
            ok = True
            for i in range(3):
                for j in range(3):
                    same = 0
                    color = bits[i*3 + j]
                    for di,dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ni, nj = i+di, j+dj
                        if 0 <= ni < 3 and 0 <= nj < 3:
                            if bits[ni*3 + nj] == color:
                                same += 1
                    if same > 1:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                total += 1
        total %= (10**9+7)
        out = run(x).strip()
        assert out == str(total), f"3x3 should be {total}, got {out}"
    if n == 3 and m == 4:
        # Too large for brute force (2^12=4096, okay).
        import itertools
        total = 0
        for bits in itertools.product([0,1], repeat=12):
            ok = True
            for i in range(3):
                for j in range(4):
                    same = 0
                    color = bits[i*4 + j]
                    for di,dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ni, nj = i+di, j+dj
                        if 0 <= ni < 3 and 0 <= nj < 4:
                            if bits[ni*4 + nj] == color:
                                same += 1
                    if same > 1:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
