tests_src:
def test_boundedness(run, x):
    N = int(x.strip())
    ans_str = run(x)
    ans = int(ans_str.strip())
    assert 0 <= ans <= N

def test_integer_output(run, x):
    ans_str = run(x)
    try:
        int(ans_str.strip())
    except ValueError:
        assert False, 'Output is not an integer'

def test_monotonicity(run, x):
    N = int(x.strip())
    if N > 1:
        smaller = str(N-1) + '\n'
        ans1 = int(run(smaller).strip())
        ans2 = int(run(x).strip())
        assert ans1 <= ans2, f'Count decreased when N increased from {N-1} to {N}'

def test_certificate_bruteforce(run, x):
    N = int(x.strip())
    # brute‑force true count
    def divisors(k):
        cnt = 0
        for d in range(1, int(k**0.5)+1):
            if k % d == 0:
                cnt += 1
                if d != k//d:
                    cnt += 1
        return cnt
    true_cnt = 0
    for k in range(1, N+1, 2):  # odd only
        if divisors(k) == 8:
            true_cnt += 1
    ans = int(run(x).strip())
    assert ans == true_cnt

def test_certificate_exact_bruteforce_all(run, x):
    N = int(x.strip())
    # same as previous but we recompute to be safe
    def count_odd_eight_divisors(limit):
        cnt = 0
        for n in range(1, limit+1, 2):
            d = 0
            for i in range(1, int(n**0.5)+1):
                if n % i == 0:
                    d += 1
                    if i != n//i:
                        d += 1
            if d == 8:
                cnt += 1
        return cnt
    expected = count_odd_eight_divisors(N)
    got = int(run(x).strip())
    assert got == expected

def test_certificate_at_least_one_witness(run, x):
    N = int(x.strip())
    ans = int(run(x).strip())
    if ans > 0:
        # find at least one qualifying number ≤ N
        found = False
        for k in range(1, N+1, 2):
            d = 0
            for i in range(1, int(k**0.5)+1):
                if k % i == 0:
                    d += 1
                    if i != k//i:
                        d += 1
            if d == 8:
                found = True
                break
        assert found, f'Answer says {ans} but no odd number with 8 divisors found ≤ {N}'

def test_monotonicity_against_smaller_fixed(run, x):
    N = int(x.strip())
    # compare with N//2 (still valid N)
    N2 = max(1, N//2)
    smaller = str(N2) + '\n'
    ans_small = int(run(smaller).strip())
    ans_big = int(run(x).strip())
    assert ans_small <= ans_big

def test_monotonicity_against_105(run, x):
    N = int(x.strip())
    ans = int(run(x).strip())
    ans105 = int(run('105\n').strip())
    if N >= 105:
        assert ans >= ans105
    else:
        assert ans <= ans105

def test_monotonicity_pair_135_189(run, x):
    # 135 and 189 are thresholds in the code
    ans135 = int(run('135\n').strip())
    ans189 = int(run('189\n').strip())
    assert ans135 <= ans189

def test_monotonicity_pair_189_195(run, x):
    ans189 = int(run('189\n').strip())
    ans195 = int(run('195\n').strip())
    assert ans189 <= ans195

