tests_src:
def test_output_length(run, x):
    out = run(x).strip()
    # The label's first three characters are printed, so output must be exactly 3 chars.
    assert len(out) == 3, f'Output length is {len(out)}, should be 3'

def test_valid_prefix(run, x):
    out = run(x).strip()
    # From the specification, the first three characters are either ABC or ABD.
    assert out in {'ABC', 'ABD'}, f'Output must be ABC or ABD, got {out}'

def test_known_cases(run, x):
    # For inputs explicitly given in the statement, we know the correct output.
    # This is allowed because the statement defines these examples.
    if x.strip() == '999':
        assert run(x).strip() == 'ABC'
    if x.strip() == '1000':
        assert run(x).strip() == 'ABD'
    if x.strip() == '1':
        assert run(x).strip() == 'ABC'

def test_metamorphic_add_999(run, x):
    n = int(x.strip())
    if n <= 999:  # n + 999 stays within 1998 limit
        m = n + 999
        out1 = run(str(n)).strip()
        out2 = run(str(m)).strip()
        # If n < 1000, n+999 >= 1000, so prefix should flip from ABC to ABD.
        # If n == 1000 or more, both are ABD.
        if n < 1000:
            assert out1 == 'ABC' and out2 == 'ABD', f'Metamorphic fail: n={n} -> {out1}, n+999={m} -> {out2}'
        else:
            assert out1 == 'ABD' and out2 == 'ABD', f'Metamorphic fail: both should be ABD for n={n}, got {out1} and {out2}'

def test_metamorphic_cross_999(run, x):
    n = int(x.strip())
    if n == 999:
        out999 = run('999').strip()
        out1000 = run('1000').strip()
        assert out999 == 'ABC' and out1000 == 'ABD', f'Crossing 999 must change prefix: 999->{out999}, 1000->{out1000}'

def test_metamorphic_adjacent(run, x):
    n = int(x.strip())
    if n < 1998:
        out_n = run(str(n)).strip()
        out_next = run(str(n+1)).strip()
        # Adjacent N should have same prefix unless crossing from 999 to 1000.
        if n == 999:
            assert out_n == 'ABC' and out_next == 'ABD'
        else:
            assert out_n == out_next, f'Adjacent N={n} and {n+1} should have same prefix, got {out_n} vs {out_next}'

def test_ascii_bounds(run, x):
    out = run(x).strip()
    # Each character is uppercase English letter, so ASCII between 65 and 90.
    for ch in out:
        assert 65 <= ord(ch) <= 90, f'Character {ch} not uppercase letter'

def test_prefix_starts_with_AB(run, x):
    out = run(x).strip()
    # The first two characters are always 'AB' in both ABC and ABD.
    assert out.startswith('AB'), f'Output does not start with AB: {out}'

def test_third_letter_C_or_D(run, x):
    out = run(x).strip()
    # The third character is either 'C' or 'D'.
    assert out[2] in {'C', 'D'}, f'Third character must be C or D, got {out[2]}'

def test_certificate_reconstruct_label(run, x):
    n = int(x.strip())
    out = run(x).strip()
    # From the specification: if prefix is ABC, then N <= 999; if ABD, then N >= 1000.
    if out == 'ABC':
        assert 1 <= n <= 999, f'Prefix ABC but N={n} is not in [1,999]'
    else:
        assert 1000 <= n <= 1998, f'Prefix ABD but N={n} is not in [1000,1998]'

