def test_output_is_ABC_or_ABD(run, x):
    out = run(x).strip()
    assert out in ('ABC', 'ABD'), f'Output must be ABC or ABD, got {repr(out)}'

def test_certificate_matches_rule(run, x):
    n = int(x.strip())
    out = run(x).strip()
    expected = 'ABC' if n < 1000 else 'ABD'
    assert out == expected, f'For N={n} expected {expected}, got {out}'

def test_monotonic_non_decreasing(run, x):
    n = int(x.strip())
    if n >= 1998:
        return  # cannot compare n+1
    out1 = run(x).strip()
    out2 = run(f'{n+1}\n').strip()
    # Lexicographic order: 'ABC' < 'ABD'
    assert out1 <= out2, f'Prefix decreased from {out1} at N={n} to {out2} at N={n+1}'

def test_length_three(run, x):
    out = run(x).strip()
    assert len(out) == 3, f'Output length must be 3, got {len(out)}'

def test_constant_except_at_999(run, x):
    n = int(x.strip())
    if n == 999:
        return  # handled separately
    if n >= 1998:
        return  # no n+1
    out1 = run(x).strip()
    out2 = run(f'{n+1}\n').strip()
    assert out1 == out2, f'Prefix changed between N={n} and N={n+1} but N != 999'

def test_change_at_999(run, x):
    n = int(x.strip())
    if n != 999:
        return
    out1 = run(x).strip()
    out2 = run('1000\n').strip()
    assert out1 != out2, f'Prefix should change at N=999, but both are {out1}'

def test_shift_by_999_diff_if_ge_1000(run, x):
    n = int(x.strip())
    if n < 1000:
        return
    # n >= 1000
    out1 = run(x).strip()
    out2 = run(f'{n-999}\n').strip()
    assert out1 != out2, f'Prefix for N={n} and N={n-999} should differ'

def test_shift_by_999_diff_if_le_999(run, x):
    n = int(x.strip())
    if n > 999:
        return
    # n <= 999
    if n + 999 > 1998:
        return  # out of range
    out1 = run(x).strip()
    out2 = run(f'{n+999}\n').strip()
    assert out1 != out2, f'Prefix for N={n} and N={n+999} should differ'

def test_no_whitespace(run, x):
    out = run(x)
    assert out == out.strip(), f'Output contains leading/trailing whitespace: {repr(out)}'

def test_special_cases_from_statement(run, x):
    n = int(x.strip())
    out = run(x).strip()
    if n == 999:
        assert out == 'ABC', f'For N=999, output must be ABC, got {out}'
    if n == 1000:
        assert out == 'ABD', f'For N=1000, output must be ABD, got {out}'
    if n == 1:
        assert out == 'ABC', f'For N=1, output must be ABC, got {out}'

def test_output_format(run, x):
    out = run(x).strip()
    # must be either 'inf' or an integer
    if out == 'inf':
        return
    # must be decimal integer possibly with minus? No, count non‑negative.
    # allow leading zeros? We'll just ensure it's digit string.
    assert out.isdigit() or (out[0] == '-' and out[1:].isdigit()), 'output must be integer or inf'
    # if negative, that's wrong
    if out[0] == '-':
        assert False, 'negative output not allowed'

def test_integer_range(run, x):
    out = run(x).strip()
    if out == 'inf':
        return
    val = int(out)
    MOD = 10**9 + 7
    assert 0 <= val < MOD, 'integer output must be in [0, MOD-1]'

def test_inf_only_if_all_one(run, x):
    out = run(x).strip()
    if out == 'inf':
        t, a, b = map(int, x.strip().split())
        assert t == 1 and a == 1 and b == 1, "'inf' only possible when t=a=b=1"

