def test_output_is_one_of_four_strings(run, x):
    out = run(x).strip()
    assert out in ("need tree", "automaton", "array", "both")

def test_if_sorted_equal_then_not_automaton_or_need_tree(run, x):
    s, t = x.strip().split('\n')[:2]
    if sorted(s) == sorted(t):
        out = run(x).strip()
        assert out in ("array", "both")

def test_if_identical_then_array(run, x):
    s, t = x.strip().split('\n')[:2]
    if s == t:
        out = run(x).strip()
        assert out == "array"

def test_if_s_is_subsequence_of_t_then_need_tree(run, x):
    s, t = x.strip().split('\n')[:2]
    if len(s) >= len(t):
        i = 0
        for c in s:
            if i < len(t) and c == t[i]:
                i += 1
        if i == len(t):
            # t is subsequence of s, not the other way
            pass
    else:
        i = 0
        for c in t:
            if i < len(s) and c == s[i]:
                i += 1
        if i == len(s):
            # s is subsequence of t, impossible to get longer t from shorter s
            out = run(x).strip()
            assert out == "need tree"

def test_if_t_subsequence_of_s_then_not_array_or_both(run, x):
    s, t = x.strip().split('\n')[:2]
    if len(s) >= len(t):
        i = 0
        for c in s:
            if i < len(t) and c == t[i]:
                i += 1
        if i == len(t):
            out = run(x).strip()
            assert out in ("automaton", "need tree")

def test_if_sorted_equal_then_not_automaton(run, x):
    s, t = x.strip().split('\n')[:2]
    if sorted(s) == sorted(t):
        out = run(x).strip()
        assert out != "automaton"

def test_if_len_s_less_than_len_t_then_need_tree(run, x):
    s, t = x.strip().split('\n')[:2]
    if len(s) < len(t):
        out = run(x).strip()
        assert out == "need tree"

def test_if_sorted_s_subsequence_of_sorted_t_then_not_automaton(run, x):
    s, t = x.strip().split('\n')[:2]
    sx, tx = sorted(s), sorted(t)
    i = 0
    for c in sx:
        if i < len(tx) and c == tx[i]:
            i += 1
    if i == len(tx):
        # sx is subsequence of tx -> need both or array
        out = run(x).strip()
        assert out in ("array", "both")

def test_if_automaton_then_t_subsequence_of_s_and_sorted_not_equal(run, x):
    out = run(x).strip()
    if out == "automaton":
        s, t = x.strip().split('\n')[:2]
        i = 0
        for c in s:
            if i < len(t) and c == t[i]:
                i += 1
        assert i == len(t)
        assert sorted(s) != sorted(t)

def test_if_both_then_sorted_s_subsequence_of_sorted_t_and_t_not_subsequence_of_s(run, x):
    out = run(x).strip()
    if out == "both":
        s, t = x.strip().split('\n')[:2]
        sx, tx = sorted(s), sorted(t)
        i = 0
        for c in sx:
            if i < len(tx) and c == tx[i]:
                i += 1
        assert i == len(tx)
        # t is not subsequence of s (otherwise automaton)
        j = 0
        for c in s:
            if j < len(t) and c == t[j]:
                j += 1
        assert j != len(t)

