    t, a, b = map(int, x.strip().split())
    if t == 2 and a == 3 and b >= 10000:
        out = run(x).strip()
        # Compute using else branch (assuming rest of code correct)
        # This is a metamorphic relation: if we change b to 3, answer should be 1.
        # But we cannot change input here. Instead, we check that if (a-b) % (t-a) == 0 and t != b,
        # then output should be 1, because for b=3 it is 1 and condition holds.
        # However, the condition for b=3: (3-3)%(2-3)=0, t!=b false (2!=3 true), so output 1.
        # For large b, if condition holds and t!=b, same formula gives 1.
        # So we assert that.
        if (a - b) % (t - a) == 0 and t != b:
