    output = run(x).strip()
    assert output in ("YES", "NO"), f"Output must be YES or NO, got {repr(output)}"


def test_yes_necessary(run, x):
    a, b = map(int, x.split())
    output = run(x).strip()
    if output == "YES":
        assert abs(a - b) <= 1, f"YES but |a-b|={abs(a-b)} > 1"
        assert a + b > 0, f"YES but a+b={a+b} <= 0"


def test_yes_sufficient(run, x):
    a, b = map(int, x.split())
    output = run(x).strip()
    if abs(a - b) <= 1 and a + b > 0:
        assert output == "YES", f"Condition holds but output is {output}"


def test_symmetry(run, x):
    a, b = map(int, x.split())
    out1 = run(x).strip()
    swapped_input = f"{b} {a}\n"
    out2 = run(swapped_input).strip()
    assert out1 == out2, f"Asymmetry: ({a},{b})->{out1}, ({b},{a})->{out2}"


def test_bruteforce_certificate(run, x):
    a, b = map(int, x.split())
    output = run(x).strip()
    # search bound: we need up to step 2*max(a,b)+2
    bound = 2 * max(a, b) + 2
    # Ensure bound at least something for small numbers
    if bound < 10:
        bound = 10
    found = False
    for l in range(1, bound + 1):
        for r in range(l, bound + 1):
            # count evens and odds in [l, r]
            length = r - l + 1
            # parity of l determines counts
            if l % 2 == 0:
                evens = (length + 1) // 2 if length % 2 == 1 else length // 2
                odds = length - evens
            else:
                odds = (length + 1) // 2 if length % 2 == 1 else length // 2
                evens = length - odds
            if evens == a and odds == b:
                found = True
                break
        if found:
            break
    if found:
        assert output == "YES", f"Interval exists but output is {output}"
    else:
        assert output == "NO", f"No interval found up to {bound} but output is {output}"


def test_zero_zero(run, x):
    a, b = map(int, x.split())
    if a == 0 and b == 0:
        output = run(x).strip()
        assert output == "NO", f"(0,0) must be NO, got {output}"


def test_yes_total_positive(run, x):
    a, b = map(int, x.split())
    output = run(x).strip()
    if output == "YES":
        assert a + b > 0, f"YES but total steps zero"


def test_yes_counts_difference(run, x):
    a, b = map(int, x.split())
    output = run(x).strip()
    if output == "YES":
        assert abs(a - b) <= 1, f"YES but |a-b|={abs(a-b)} > 1"


def test_no_implies_condition_false(run, x):
    a, b = map(int, x.split())
    output = run(x).strip()
    if output == "NO":
        assert abs(a - b) > 1 or a + b == 0, f"NO but condition (|a-b|<=1 and a+b>0) holds"


def test_output_ends_with_newline(run, x):
    output = run(x)
    assert output.endswith("\n"), f"Output must end with newline"

def test_output_sorted_distinct(run, x):
    out = run(x).strip()
    # output must be empty or sorted and no duplicates
    if out:
        assert list(out) == sorted(set(out)), "Output not sorted or has duplicates"

def test_output_subset_of_input_chars(run, x):
    out = run(x).strip()
    s = x.split('\n')[1]  # second line of input (first line is t, but here t=1 always)
    # careful: x may have trailing newline, but split works.
    input_chars = set(s)
    assert set(out) <= input_chars, "Output contains character not in input string"

def test_single_occurrence_must_be_in_output(run, x):
    s = x.split('\n')[1]
    from collections import Counter
    cnt = Counter(s)
    singles = {c for c, v in cnt.items() if v == 1}
    out = set(run(x).strip())
    for c in singles:
        assert c in out, f"Character {c} appears exactly once but not in output"

def test_odd_count_must_be_in_output(run, x):
    s = x.split('\n')[1]
    from collections import Counter
    cnt = Counter(s)
    odd_chars = {c for c, v in cnt.items() if v % 2 == 1}
    out = set(run(x).strip())
    for c in odd_chars:
        assert c in out, f"Character {c} appears odd number of times but not in output"

def test_output_chars_have_isolated_occurrence(run, x):
    s = x.split('\n')[1]
    out = set(run(x).strip())
    n = len(s)
    isolated = set()
    for i, ch in enumerate(s):
        left_ok = (i == 0 or s[i-1] != ch)
        right_ok = (i == n-1 or s[i+1] != ch)
        if left_ok and right_ok:
            isolated.add(ch)
    # For each character in output, there must be at least one isolated occurrence
    for c in out:
        assert c in isolated, f"Character {c} in output but no isolated occurrence found"

def test_if_length_odd_output_not_empty(run, x):
    s = x.split('\n')[1]
    if len(s) % 2 == 1:
        out = run(x).strip()
        assert out != "", "String length odd but output empty"

def test_output_length_le_distinct(run, x):
    s = x.split('\n')[1]
    out = run(x).strip()
    assert len(out) <= len(set(s)), "Output length exceeds number of distinct characters in input"

def test_chars_with_isolated_occurrence_subset_of_output(run, x):
    s = x.split('\n')[1]
    n = len(s)
    isolated = set()
    for i, ch in enumerate(s):
        left_ok = (i == 0 or s[i-1] != ch)
        right_ok = (i == n-1 or s[i+1] != ch)
        if left_ok and right_ok:
            isolated.add(ch)
    out = set(run(x).strip())
    # Every character that has an isolated occurrence must be in output
    for c in isolated:
        assert c in out, f"Character {c} has isolated occurrence but not in output"

def test_output_subset_of_greedy_singles(run, x):
    s = x.split('\n')[1]
    i = 0
    greedy_singles = set()
    while i < len(s):
        if i == len(s) - 1 or s[i] != s[i+1]:
            greedy_singles.add(s[i])
            i += 1
        else:
            i += 2
    out = set(run(x).strip())
    assert out <= greedy_singles, f"Output contains characters not working in greedy parsing"

def test_output_no_repeats(run, x):
    out = run(x).strip()
    assert len(out) == len(set(out)), "Output has duplicate characters"

