def test_output_format(run, x):
    out = run(x)
    assert out in ('YES\n', 'NO\n'), f'Output must be YES or NO followed by newline, got {repr(out)}'

def test_change_possible_implies_YES(run, x):
    # If we can simulate giving change correctly, answer must be YES.
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    bills = list(map(int, lines[1].split()))
    cash25 = 0
    cash50 = 0
    possible = True
    for b in bills:
        if b == 25:
            cash25 += 1
        elif b == 50:
            if cash25 >= 1:
                cash25 -= 1
                cash50 += 1
            else:
                possible = False
                break
        else:  # 100
            if cash50 >= 1 and cash25 >= 1:
                cash50 -= 1
                cash25 -= 1
            elif cash25 >= 3:
                cash25 -= 3
            else:
                possible = False
                break
    if possible:
        out = run(x)
        assert out == 'YES\n', f'Should be YES when change possible, got {out}'

def test_YES_implies_change_possible(run, x):
    out = run(x)
    if out == 'YES\n':
        lines = x.strip().split('\n')
        if len(lines) < 2:
            return
        bills = list(map(int, lines[1].split()))
        cash25 = 0
        cash50 = 0
        for b in bills:
            if b == 25:
                cash25 += 1
            elif b == 50:
                if cash25 >= 1:
                    cash25 -= 1
                    cash50 += 1
                else:
                    assert False, 'Output YES but change impossible at 50'
            else:  # 100
                if cash50 >= 1 and cash25 >= 1:
                    cash50 -= 1
                    cash25 -= 1
                elif cash25 >= 3:
                    cash25 -= 3
                else:
                    assert False, 'Output YES but change impossible at 100'

def test_total_money_conservation(run, x):
    # Total money (clerk's cash + people's paid bills) is constant.
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    bills = list(map(int, lines[1].split()))
    total_paid = sum(bills)
    ticket_cost = 25 * len(bills)
    # Clerk ends with cash = total_paid - ticket_cost
    # That must be non‑negative (but that's already covered by change simulation).
    # Simulate with the submitted code's logic? No, we can just compute total cash after.
    # Instead, we just note that total_paid >= ticket_cost is necessary but not sufficient.
    # This is a very weak property, but it's still true.
    out = run(x)
    if out == 'YES\n':
        assert total_paid >= ticket_cost, 'YES but total paid less than total cost'

def test_no_negative_change(run, x):
    # Clerk's cash (25 and 50 bills) never goes negative in our own simulation.
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    bills = list(map(int, lines[1].split()))
    cash25 = 0
    cash50 = 0
    for b in bills:
        if b == 25:
            cash25 += 1
        elif b == 50:
            cash25 -= 1
            if cash25 < 0:
                assert False, 'Cash25 went negative at 50'
            cash50 += 1
        else:  # 100
            if cash50 >= 1:
                cash50 -= 1
                cash25 -= 1
            else:
                cash25 -= 3
            if cash25 < 0 or cash50 < 0:
                assert False, 'Cash went negative at 100'

def test_YES_on_all_25(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    bills = list(map(int, lines[1].split()))
    if all(b == 25 for b in bills):
        out = run(x)
        assert out == 'YES\n', 'All 25 must yield YES'

def test_NO_if_sum_less_than_cost(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    bills = list(map(int, lines[1].split()))
    total_paid = sum(bills)
    ticket_cost = 25 * len(bills)
    if total_paid < ticket_cost:
        out = run(x)
        assert out == 'NO\n', 'Total paid less than cost must yield NO'

def test_order_invariant_swap_adjacent_equal(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    parts = lines[1].split()
    bills = list(map(int, parts))
    # Find two adjacent equal bills and swap them (no effect).
    for i in range(len(bills)-1):
        if bills[i] == bills[i+1]:
            new_bills = bills[:]
            new_bills[i], new_bills[i+1] = new_bills[i+1], new_bills[i]
            new_input = f'{len(new_bills)}\n' + ' '.join(map(str, new_bills)) + '\n'
            out1 = run(x)
            out2 = run(new_input)
            assert out1 == out2, f'Swapping adjacent equal bills changed answer'
            break  # only need one such pair

def test_metamorphic_add_two_25_at_start(run, x):
    # Adding two 25‑ruble bills at the start: each pays exactly for a ticket, no change needed.
    # So answer should stay the same.
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    bills = list(map(int, lines[1].split()))
    new_n = n + 2
    new_bills = [25, 25] + bills
    new_input = f'{new_n}\n' + ' '.join(map(str, new_bills)) + '\n'
    out1 = run(x)
    out2 = run(new_input)
    assert out1 == out2, 'Adding two 25 at start should not change answer'

def test_metamorphic_remove_pair_25_50(run, x):
    # If the line starts with 25 then 50, they can be removed together:
    # first pays 25, gets ticket; second pays 50, gets 25 change, clerk ends with 0 net cash.
    # So answer should stay the same.
    lines = x.strip().split('\n')
