    if len(parts) < 2:
        return
    if int(parts[0]) == 25 and int(parts[1]) == 50:
        bills = list(map(int, parts))
        new_bills = bills[2:]
        new_n = len(new_bills)
        new_input = f'{new_n}\n' + ' '.join(map(str, new_bills)) + '\n'
        out1 = run(x)
        out2 = run(new_input)
        assert out1 == out2, 'Removing a 25‑50 pair from start should not change answer'

