def test_move_board_consistent_with_all_pieces(run, x):
    # This is essentially the same as certificate reconstruction, but we'll keep it as a separate test for robustness.
    out = run(x).strip()
    lines = out.split('\n')
    if lines[0] == 'NO':
        return
    n = int(x.split('\n')[0].strip())
    input_lines = x.strip().split('\n')[1:]
    move_board = lines[1:]
    # For each piece, and for each move, if the move lands on a '.' then that move must be absent.
    # But the move board is global, so we need to ensure that for every piece, the moves that land on '.' are not present.
    # Actually the move board is the set of moves; if a move is present, it might land on a '.' from some piece, which is illegal.
    # The specification says: a cell is attacked if some piece can move to it. So if a cell is '.', no piece can move to it.
    # Therefore, for every piece and every cell that is '.', the move (cell - piece) must not be in the move set.
    moves_set = set()
    for dx in range(-n+1, n):
        for dy in range(-n+1, n):
            if move_board[n-1+dx][n-1+dy] == 'x':
                moves_set.add((dx, dy))
    for i in range(n):
        for j in range(n):
            if input_lines[i][j] == 'o':
                for x2 in range(n):
                    for y2 in range(n):
                        if input_lines[x2][y2] == '.':
                            dx = x2 - i
                            dy = y2 - j
                            assert (dx, dy) not in moves_set, f'Move ({dx},{dy}) from piece ({i},{j}) lands on dot at ({x2},{y2})'

