def test_translation_invariance(run, x):
    # If we shift all pieces by the same vector (staying inside board), the move set should be the same.
    # We'll create a modified input by moving every piece one step down and right if possible.
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n < 2:
        return
    input_grid = [list(row) for row in lines[1:]]
    # find all pieces
    pieces = [(i, j) for i in range(n) for j in range(n) if input_grid[i][j] == 'o']
    if not pieces:
        return
    # shift all pieces by (1,1) if they fit
    new_grid = [['.' for _ in range(n)] for __ in range(n)]
    for i in range(n):
        for j in range(n):
            if input_grid[i][j] == 'x':
                new_grid[i][j] = 'x'
            elif input_grid[i][j] == '.':
                new_grid[i][j] = '.'
    ok_shift = True
    for pi, pj in pieces:
        if pi+1 >= n or pj+1 >= n:
            ok_shift = False
            break
    if not ok_shift:
        return
    for pi, pj in pieces:
        new_grid[pi+1][pj+1] = 'o'
    new_input = f"{n}\n" + '\n'.join(''.join(row) for row in new_grid)
    # run original and shifted
    out1 = run(x).strip().split('\n')
    out2 = run(new_input).strip().split('\n')
    if out1[0] == 'NO' or out2[0] == 'NO':
        # either both NO or at least one YES? Not required, so we skip.
        return
    # move boards should be identical
    board1 = out1[1:]
    board2 = out2[1:]
    assert board1 == board2, "Move set should be invariant under translation of all pieces"

def test_swap_pieces(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n < 2:
        return
    input_grid = [list(row) for row in lines[1:]]
    pieces = [(i, j) for i in range(n) for j in range(n) if input_grid[i][j] == 'o']
    if len(pieces) < 2:
        return
    # swap first two pieces
    (i1, j1), (i2, j2) = pieces[0], pieces[1]
    new_grid = [row.copy() for row in input_grid]
    new_grid[i1][j1], new_grid[i2][j2] = new_grid[i2][j2], new_grid[i1][j1]
    # attacked cells remain same
    new_input = f"{n}\n" + '\n'.join(''.join(row) for row in new_grid)
    out1 = run(x).strip().split('\n')
