def test_output_length(run, x):
    s, _ = x.strip().split('\n')
    n = len(s)
    output = run(x).strip().split()
    assert len(output) == n + 1, f"Expected {n+1} numbers, got {len(output)}"


def test_non_negative(run, x):
    output = run(x).strip().split()
    for val in output:
        assert int(val) >= 0, f"Negative value {val}"


def test_upper_bound(run, x):
    s, p = x.strip().split('\n')
    n, m = len(s), len(p)
    output = list(map(int, run(x).strip().split()))
    for x_val, ans_val in enumerate(output):
        max_possible = (n - x_val) // m if m > 0 else 0
        assert ans_val <= max_possible, f"ans({x_val}) = {ans_val} exceeds upper bound {max_possible}"


def test_monotonic_non_increasing(run, x):
    output = list(map(int, run(x).strip().split()))
    for i in range(1, len(output)):
        assert output[i] <= output[i-1], f"ans increased from {output[i-1]} at x={i-1} to {output[i]} at x={i}"


def test_step_bound(run, x):
    output = list(map(int, run(x).strip().split()))
    for i in range(1, len(output)):
        assert output[i] >= output[i-1] - 1, f"ans dropped by more than 1 from {output[i-1]} to {output[i]}"


def test_no_occurrence_at_zero(run, x):
    s, p = x.strip().split('\n')
    output = list(map(int, run(x).strip().split()))
    if p not in s:
        assert output[0] == 0, f"p not in s but ans(0) = {output[0]}"


def test_duplicate_last(run, x):
    s, p = x.strip().split('\n')
    n = len(s)
    s2 = s + s
    input2 = f"{s2}\n{p}\n"
    out1 = list(map(int, run(x).strip().split()))
    out2 = list(map(int, run(input2).strip().split()))
    # For each x in 0..n, ans for s2 at x + n should be at least ans for s at x
    for x_val in range(n+1):
        assert out2[x_val + n] >= out1[x_val], f"Duplicating s: ans({x_val + n}) for s+s < ans({x_val}) for s"


def test_reversal_symmetry(run, x):
    s, p = x.strip().split('\n')
    s_rev = s[::-1]
    p_rev = p[::-1]
    input_rev = f"{s_rev}\n{p_rev}\n"
    out = list(map(int, run(x).strip().split()))
    out_rev = list(map(int, run(input_rev).strip().split()))
    assert out == out_rev, f"Reversal changes answer"


def test_zero_at_full_removal(run, x):
    s, _ = x.strip().split('\n')
    n = len(s)
    output = list(map(int, run(x).strip().split()))
    assert output[-1] == 0, f"ans({n}) should be 0, got {output[-1]}"


