def test_output_is_yes_or_no(run, x):
    output = run(x)
    lines = output.strip().split('\n')
    assert len(lines) >= 1, "No output"
    first = lines[0].strip()
    assert first in ("Yes", "No"), f"Invalid output '{first}'"

def test_if_yes_rectangle_consistent(run, x):
    output = run(x).strip()
    if output != "Yes":
        return
    # parse grid
    lines = x.strip().split('\n')
    N = int(lines[0])
    grid = [list(map(int, line.strip())) for line in lines[1:1+N]]
    # find rectangle from 4-cells
    x1 = N
    y1 = N
    x2 = -1
    y2 = -1
    for y in range(N):
        for x in range(N):
            if grid[y][x] == 4:
                x1 = min(x1, x)
                y1 = min(y1, y)
                x2 = max(x2, x)
                y2 = max(y2, y)
    if x2 < 0:
        # no 4-cells, but answer is Yes? impossible.
        assert False, "Yes but no 4-cells"
    # compute expected contamination for each cell
    for y in range(N):
        for x in range(N):
            ex = 0
            if x1 <= x <= x2 and y1 <= y <= y2:
                ex = 4
            elif ((x == x1-1 or x == x2+1) and y1 <= y <= y2):
                ex = 2
            elif ((y == y1-1 or y == y2+1) and x1 <= x <= x2):
                ex = 2
            elif ((x == x1-1 or x == x2+1) and (y == y1-1 or y == y2+1)):
                ex = 1
            if ex != grid[y][x]:
                assert False, f"Mismatch at ({x},{y}): expected {ex}, got {grid[y][x]}"

def test_no_4_cells_implies_no(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    grid = [list(map(int, line.strip())) for line in lines[1:1+N]]
    has4 = any(4 in row for row in grid)
    if not has4:
        output = run(x).strip()
        assert output == "No", f"No 4-cells but output is {output}"

def test_add_zero_border_preserves_answer(run, x):
    # add a border of zeros around the whole grid
    lines = x.strip().split('\n')
    N = int(lines[0])
    orig_grid = [list(map(int, line.strip())) for line in lines[1:1+N]]
    newN = N + 2
    new_grid = [[0]*newN for _ in range(newN)]
    for y in range(N):
        for x in range(N):
            new_grid[y+1][x+1] = orig_grid[y][x]
    new_input = f"{newN}\
" + '\n'.join(''.join(str(v) for v in row) for row in new_grid) + '\n'
    orig_out = run(x).strip()
    new_out = run(new_input).strip()
    assert orig_out == new_out, f"Border changed answer: {orig_out} -> {new_out}"

def test_if_yes_grid_symmetric_180(run, x):
    output = run(x).strip()
    if output != "Yes":
        return
    lines = x.strip().split('\n')
    N = int(lines[0])
    grid = [list(map(int, line.strip())) for line in lines[1:1+N]]
    for y in range(N):
        for x in range(N):
            y2 = N-1 - y
            x2 = N-1 - x
            assert grid[y][x] == grid[y2][x2], f"Grid not 180-degree symmetric at ({x},{y})"

def test_if_no_rectangle_from_4_fails(run, x):
    output = run(x).strip()
    if output != "No":
        return
    lines = x.strip().split('\n')
    N = int(lines[0])
    grid = [list(map(int, line.strip())) for line in lines[1:1+N]]
    # find rectangle from 4-cells
    x1 = N
    y1 = N
    x2 = -1
    y2 = -1
    for y in range(N):
        for x in range(N):
            if grid[y][x] == 4:
                x1 = min(x1, x)
                y1 = min(y1, y)
                x2 = max(x2, x)
                y2 = max(y2, y)
    if x2 < 0:
        return  # no 4-cells, fine
    # check if this rectangle actually matches grid
    mismatch = False
    for y in range(N):
        for x in range(N):
            ex = 0
            if x1 <= x <= x2 and y1 <= y <= y2:
                ex = 4
            elif ((x == x1-1 or x == x2+1) and y1 <= y <= y2):
                ex = 2
            elif ((y == y1-1 or y == y2+1) and x1 <= x <= x2):
                ex = 2
            elif ((x == x1-1 or x == x2+1) and (y == y1-1 or y == y2+1)):
                ex = 1
            if ex != grid[y][x]:
                mismatch = True
                break
        if mismatch:
            break
    else:
        # rectangle matches, but output is No → contradiction
        assert False, "Rectangle from 4-cells matches but output is No"

def test_counts_of_4_bounded(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    grid = [list(map(int, line.strip())) for line in lines[1:1+N]]
    count4 = sum(row.count(4) for row in grid)
    assert 0 <= count4 <= N*N, "Invalid number of 4-cells"
    output = run(x).strip()
    if output == "Yes":
        assert count4 >= 1, "Yes but no 4-cells"

def test_no_value_3_allowed(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    grid = [list(map(int, line.strip())) for line in lines[1:1+N]]
    for y in range(N):
        for x in range(N):
            assert grid[y][x] in (0,1,2,4), f"Value 3 at ({x},{y})"

def test_flip_horizontal_preserves_answer(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    orig_grid = [list(map(int, line.strip())) for line in lines[1:1+N]]
    # flip horizontally (reverse each row)
    flipped = [row[::-1] for row in orig_grid]
    flipped_input = f"{N}\
" + '\n'.join(''.join(str(v) for v in row) for row in flipped) + '\n'
    orig_out = run(x).strip()
    flipped_out = run(flipped_input).strip()
    assert orig_out == flipped_out, f"Flip horizontal changed answer: {orig_out} -> {flipped_out}"

def test_output_ends_with_newline(run, x):
    output = run(x)
    assert output.endswith('\n'), "Output does not end with newline"

