def test_non_negative(run, x):
    ans = int(run(x).strip())
    assert ans >= 0

def test_symmetry(run, x):
    N, M = map(int, x.strip().split())
    swapped = f'{M} {N}\n'
    ans1 = int(run(x).strip())
    ans2 = int(run(swapped).strip())
    assert ans1 == ans2

def test_monotonic_N(run, x):
    N, M = map(int, x.strip().split())
    if N < 10**9:
        larger = f'{N+1} {M}\n'
        ans1 = int(run(x).strip())
        ans2 = int(run(larger).strip())
        # Adding a row cannot decrease the number of down cards.
        # Reason: operations on the extra row only flip cards in that row and adjacent,
        # but overall parity of each card depends on total flips; monotonicity holds because
        # the count of down cards is (max(0,N-2))*(max(0,M-2)) for N,M≥1, which is non‑decreasing in N.
        assert ans2 >= ans1

def test_monotonic_M(run, x):
    N, M = map(int, x.strip().split())
    if M < 10**9:
        larger = f'{N} {M+1}\n'
        ans1 = int(run(x).strip())
        ans2 = int(run(larger).strip())
        assert ans2 >= ans1

def test_small_1x1(run, x):
    if x.strip() == '1 1':
        assert int(run(x).strip()) == 1

def test_small_2x2(run, x):
    if x.strip() == '2 2':
        assert int(run(x).strip()) == 0

def test_small_1xM(run, x):
    N, M = map(int, x.strip().split())
    if N == 1 and M >= 2:
        # For 1×M, only the two edge cells are flipped 4 times (up), interior cells are flipped 2 times (down).
        # Correct formula: max(0, M-2).
        ans = int(run(x).strip())
        assert ans == M - 2

def test_small_Nx1(run, x):
    N, M = map(int, x.strip().split())
    if M == 1 and N >= 2:
        ans = int(run(x).strip())
        assert ans == N - 2

def test_interior_bound(run, x):
    N, M = map(int, x.strip().split())
    if N >= 3 and M >= 3:
        ans = int(run(x).strip())
        # Each interior cell is flipped 9 times (odd → down).
        # There are (N-2)*(M-2) interior cells, so down cards ≤ that.
        # Actually it's exactly that, but we only check bound.
        assert ans <= (N-2)*(M-2)

def test_known_3x3(run, x):
    if x.strip() == '3 3':
        # Center cell flipped 9 times (down), others flipped even times (up).
        assert int(run(x).strip()) == 1

