def test_output_length_matches_k(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    output = run(x).strip()
    if output:
        out_lines = output.split()
        assert len(out_lines) == k, f'Expected {k} numbers, got {len(out_lines)}'
    else:
        assert k == 0, f'Expected {k} numbers, got empty output'

def test_answer_non_negative(run, x):
    output = run(x).strip()
    if output:
        for val in output.split():
            assert int(val) >= 0, f'Negative answer {val}'

def test_answer_same_within_component(run, x):
    # For each start, we can compute component by BFS (fast for these inputs).
    # Then check all starts in same component give same answer.
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:1+n]]
    starts = [tuple(map(int, line.split())) for line in lines[1+n:1+n+k]]
    # Adjust to 0-index
    starts = [(x-1, y-1) for x, y in starts]
    output = run(x).strip()
    if not output:
        return
    answers = list(map(int, output.split()))
    # Compute components
    comp_id = [[-1]*m for _ in range(n)]
    comp_val = {}
    from collections import deque
    comp_index = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j]=='.' and comp_id[i][j]==-1:
                q = deque([(i,j)])
                comp_id[i][j]=comp_index
                while q:
                    ci,cj = q.popleft()
                    for di,dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ni,nj = ci+di, cj+dj
                        if 0<=ni<n and 0<=nj<m and grid[ni][nj]=='.' and comp_id[ni][nj]==-1:
                            comp_id[ni][nj]=comp_index
                            q.append((ni,nj))
                comp_index+=1
    # For each start, store answer for its component
    for idx, (sx,sy) in enumerate(starts):
        cid = comp_id[sx][sy]
        if cid not in comp_val:
            comp_val[cid]=answers[idx]
        else:
            assert comp_val[cid]==answers[idx], f'Different answers in same component: {comp_val[cid]} vs {answers[idx]}'

def test_answer_upper_bound_total_walls(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:1+n]]
    # total possible walls: each cell has up to 4 sides, but each wall counted twice.
    # easier: count edges between '.' and '*'.
    total = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j]=='.':
                for di,dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                    ni,nj = i+di, j+dj
                    if 0<=ni<n and 0<=nj<m and grid[ni][nj]=='*':
                        total+=1
    # each wall counted once because we only count from '.' side.
    output = run(x).strip()
    if output:
        for val in output.split():
            assert int(val) <= total, f'Answer {val} exceeds total walls {total}'

