    new_lines.append(''.join(new_grid[1]))
    for i in range(2,n):
        new_lines.append(''.join(grid[i]))  # unchanged
    for x,y in new_starts:
        new_lines.append(f'{x} {y}')
    new_input = '\n'.join(new_lines)
