tests_src:
def test_n_lines(run, x):
    n = int(x.strip())
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    assert len(lines) == n, f'Expected {n} lines, got {len(lines)}'

def test_line_lengths(run, x):
    n = int(x.strip())
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    for i, line in enumerate(lines):
        assert len(line) == n, f'Line {i} length {len(line)} != {n}'

def test_chars_only_D_or_star(run, x):
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    for i, line in enumerate(lines):
        for ch in line:
            assert ch in 'D*', f'Invalid character {ch} in line {i}'

def test_rows_symmetric(run, x):
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    for i, line in enumerate(lines):
        assert line == line[::-1], f'Row {i} not symmetric'

def test_vertical_symmetry(run, x):
    n = int(x.strip())
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    for i in range(n):
        assert lines[i] == lines[n-1-i], f'Row {i} not equal to row {n-1-i}'

def test_middle_row_all_D(run, x):
    n = int(x.strip())
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    mid = n // 2
    assert lines[mid] == 'D' * n, f'Middle row should be all D'

def test_D_contiguous_per_row(run, x):
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    for i, line in enumerate(lines):
        # find first D and last D
        first = line.find('D')
        if first == -1:
            continue  # row with no D? Not possible for odd n >=3, but safe
        last = line.rfind('D')
        # between first and last must be all D
        for j in range(first, last+1):
            if line[j] != 'D':
                assert False, f'Row {i} has non-D inside D block'

def test_rotate_180(run, x):
    n = int(x.strip())
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    rotated = [line[::-1] for line in lines[::-1]]
    assert lines == rotated, f'Output not invariant under 180-degree rotation'

def test_D_count_symmetric_rows(run, x):
    n = int(x.strip())
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    for i in range(n):
        cnt_i = lines[i].count('D')
        cnt_sym = lines[n-1-i].count('D')
        assert cnt_i == cnt_sym, f'Row {i} has {cnt_i} D, symmetric row has {cnt_sym}'

def test_flip_horizontal(run, x):
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    for line in lines:
        assert line == line[::-1], f'Row not symmetric horizontally'

