        assert out == "YES", f'All lamps covered by >=2 switches => must be YES, got {out}'

def test_unique_cover_lamp(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    rows = lines[1:1+n]
    count = [0]*m
    for r in rows:
        for j,ch in enumerate(r.strip()):
            if ch == '1':
                count[j] += 1
    # Find lamps with count == 1 and which switch covers them
    unique_lamps = [j for j in range(m) if count[j]==1]
    if not unique_lamps:
        return
    cover_map = {}
    for i,r in enumerate(rows):
        for j in unique_lamps:
            if r[j]=='1':
                cover_map[j] = i
    # If there exists a switch that covers more than one unique lamp, answer must be NO?
    # Actually, if a switch covers any unique lamp, removing it makes that lamp uncovered.
    # So for YES, there must be a switch that covers NO unique lamps.
    # This test is a certificate: if output is YES, then there exists a switch covering none of the unique lamps.
    out = run(x).strip()
    if out == "YES":
        # find such a switch
        ok = False
        for i in range(n):
            covers_unique = any(rows[i][j]=='1' for j in unique_lamps)
            if not covers_unique:
                ok = True
                break
        assert ok, 'YES but every switch covers some uniquely covered lamp'

def test_no_certificate(run, x):
