        rows = lines[1:1+n]
        # For each switch i, there must be a lamp j that only i covers.
        count = [0]*m
        for r in rows:
            for j,ch in enumerate(r.strip()):
                if ch == '1':
                    count[j] += 1
        for i in range(n):
            has_unique = False
            for j in range(m):
                if rows[i][j]=='1' and count[j]==1:
                    has_unique = True
                    break
            assert has_unique, f'NO output but switch {i} has no uniquely covered lamp'

