    for j in range(m):
        for i1 in range(n):
            for i2 in range(i1+1, n):
                if arr[i1][j] < arr[i2][j]:
                    assert ans[i1][j] <= ans[i2][j], f'Col {j}: order broken between rows {i1},{i2}'
                elif arr[i1][j] > arr[i2][j]:
                    assert ans[i1][j] >= ans[i2][j], f'Col {j}: order broken between rows {i1},{i2}'
                else:
                    assert ans[i1][j] == ans[i2][j], f'Col {j}: equal heights must get equal answer'


