def test_answer_identical_rows(run, x):
    # If two rows are identical, their answer rows should be identical.
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    arr = [list(map(int, l.split())) for l in lines[1:]]
    out = run(x).strip()
    ans = [list(map(int, l.split())) for l in out.split('\n')]
    for i1 in range(n):
        for i2 in range(i1+1, n):
            if arr[i1] == arr[i2]:
                assert ans[i1] == ans[i2], f'Identical rows {i1},{i2} must have identical answer rows'


def test_answer_identical_cols(run, x):
    # If two columns are identical, their answer columns should be identical.
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    arr = [list(map(int, l.split())) for l in lines[1:]]
