def test_output_no_extra_whitespace(run, x):
    out = run(x).strip()
    assert out == run(x).strip(), "Output must not have leading/trailing whitespace beyond newline"

def test_if_YES_then_symmetry_possible(run, x):
    out = run(x).strip()
    if out != "YES":
        return
    H, W = map(int, x.split('\n')[0].split())
    grid = [list(line) for line in x.strip().split('\n')[1:]]
    from itertools import permutations
    rows = list(range(H))
    cols = list(range(W))
    possible = False
    for rperm in permutations(rows):
        for cperm in permutations(cols):
            ok = True
            for i in range(H):
                for j in range(W):
                    ni = H - 1 - i
                    nj = W - 1 - j
                    if grid[rperm[i]][cperm[j]] != grid[rperm[ni]][cperm[nj]]:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                possible = True
                break
        if possible:
            break
    assert possible, "YES returned but no row/column permutation yields symmetry"

def test_if_NO_then_symmetry_impossible(run, x):
    out = run(x).strip()
    if out != "NO":
        return
    H, W = map(int, x.split('\n')[0].split())
    grid = [list(line) for line in x.strip().split('\n')[1:]]
    from itertools import permutations
    rows = list(range(H))
    cols = list(range(W))
    possible = False
    for rperm in permutations(rows):
        for cperm in permutations(cols):
            ok = True
            for i in range(H):
                for j in range(W):
                    ni = H - 1 - i
                    nj = W - 1 - j
                    if grid[rperm[i]][cperm[j]] != grid[rperm[ni]][cperm[nj]]:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                possible = True
                break
        if possible:
            break
    assert not possible, "NO returned but a row/column permutation yields symmetry"

def test_swapping_all_rows_preserves_answer(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    if H <= 1:
        return
    swapped = [lines[0]] + lines[H:0:-1]
    swapped_input = '\n'.join(swapped)
    out1 = run(x).strip()
    out2 = run(swapped_input).strip()
    assert out1 == out2, "Reversing all rows must not change answer"

def test_swapping_all_columns_preserves_answer(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    if W <= 1:
        return
    new_lines = [lines[0]]
    for i in range(1, len(lines)):
        new_lines.append(lines[i][::-1])
    swapped_input = '\n'.join(new_lines)
    out1 = run(x).strip()
    out2 = run(swapped_input).strip()
    assert out1 == out2, "Reversing all columns must not change answer"

def test_transpose_swaps_row_column_check(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    transposed = [f"{W} {H}"]
    for j in range(W):
        col = ''.join(lines[i+1][j] for i in range(H))
        transposed.append(col)
    transposed_input = '\n'.join(transposed)
    out1 = run(x).strip()
    out2 = run(transposed_input).strip()
    assert out1 == out2, "Transposing grid must preserve answer (symmetry condition is invariant under transpose)"

def test_answer_is_YES_or_NO_only(run, x):
    out = run(x).strip()
    assert out == "YES" or out == "NO", f"Output must be exactly YES or NO, got {out}"

