tests_src:
def test_length_match(run, x):
    S = x.strip()
    output = run(x).strip()
    assert len(output) == len(S), f'output length {len(output)} != input length {len(S)}'

def test_all_x(run, x):
    output = run(x).strip()
    assert all(c == 'x' for c in output), f'output contains non-x: {output}'

def test_double_length(run, x):
    S = x.strip()
    if len(S) * 2 <= 100:
        doubled = S + S
        out1 = run(x).strip()
        out2 = run(doubled + '\n').strip()
        assert len(out2) == 2 * len(out1), f'doubling input should double output length'

def test_reverse_length(run, x):
    S = x.strip()
    reversed_S = S[::-1]
    out1 = run(x).strip()
    out2 = run(reversed_S + '\n').strip()
    assert len(out1) == len(out2), f'reversing input should not change output length'

def test_all_x_input(run, x):
    S = x.strip()
    if all(c == 'x' for c in S):
        output = run(x).strip()
        assert output == S, f'if input is all x, output should be identical'

def test_single_char(run, x):
    S = x.strip()
    if len(S) == 1:
        output = run(x).strip()
        assert output == 'x', f'for single character input, output must be "x"'

def test_two_same_chars(run, x):
    S = x.strip()
    if len(S) == 2 and S[0] == S[1]:
        output = run(x).strip()
        assert output == 'xx', f'for two identical chars, output must be "xx"'

def test_append_a(run, x):
    S = x.strip()
    if len(S) + 1 <= 100:
        new_S = S + 'a'
        out1 = run(x).strip()
        out2 = run(new_S + '\n').strip()
        assert len(out2) == len(out1) + 1, f'adding a character should increase output length by 1'

def test_length_nonzero(run, x):
    output = run(x).strip()
    assert 1 <= len(output) <= 100, f'output length must be between 1 and 100 (inclusive)'

def test_certificate(run, x):
    S = x.strip()
    expected = 'x' * len(S)
    output = run(x).strip()
    assert output == expected, f'output does not match expected replacement'

