tests_src:
def test_output_format(run, x):
    out = run(x)
    assert out in ('Yes\n', 'No\n'), f'Output must be Yes\\n or No\\n, got {repr(out)}'

def test_yes_implies_distance_covered(run, x):
    D, T, S = map(int, x.strip().split())
    out = run(x)
    if out == 'Yes\n':
        # If he arrives in time, the distance he can cover in T minutes (S*T) must be at least D
        assert D <= T * S, f'Yes output but D={D} > T*S={T*S}'

def test_no_implies_distance_not_covered(run, x):
    D, T, S = map(int, x.strip().split())
    out = run(x)
    if out == 'No\n':
        # If he does not arrive in time, the distance he can cover in T minutes is less than D
        assert D > T * S, f'No output but D={D} <= T*S={T*S}'

def test_scaling_distance_speed_same_factor(run, x):
    D, T, S = map(int, x.strip().split())
    # Scale D and S by same integer factor k, keep T unchanged, within constraints.
    # Choose k=2 if possible, else k=1 (no change).
    k = 2
    newD = D * k
    newS = S * k
    if 1 <= newD <= 10000 and 1 <= newS <= 10000:
        new_input = f'{newD} {T} {newS}\n'
        out1 = run(x)
        out2 = run(new_input)
        assert out1 == out2, f'Scaling D,S by {k} changed answer from {out1.strip()} to {out2.strip()}'

def test_monotonic_time_increase(run, x):
    D, T, S = map(int, x.strip().split())
    if T < 10000:
        new_input = f'{D} {T+1} {S}\n'
        out1 = run(x)
        out2 = run(new_input)
        # If with T he arrives, with T+1 he must also arrive.
        if out1 == 'Yes\n':
            assert out2 == 'Yes\n', f'Increasing T made Yes become No'

def test_monotonic_distance_decrease(run, x):
    D, T, S = map(int, x.strip().split())
    if D > 1:
        new_input = f'{D-1} {T} {S}\n'
        out1 = run(x)
        out2 = run(new_input)
        if out1 == 'Yes\n':
            assert out2 == 'Yes\n', f'Decreasing D made Yes become No'

def test_monotonic_speed_increase(run, x):
    D, T, S = map(int, x.strip().split())
    if S < 10000:
        new_input = f'{D} {T} {S+1}\n'
        out1 = run(x)
        out2 = run(new_input)
        if out1 == 'Yes\n':
            assert out2 == 'Yes\n', f'Increasing S made Yes become No'

def test_bound_not_no_if_distance_covered(run, x):
    D, T, S = map(int, x.strip().split())
    out = run(x)
    if D <= T * S:
        assert out != 'No\n', f'Should not output No when D <= T*S'

def test_bound_not_yes_if_distance_not_covered(run, x):
    D, T, S = map(int, x.strip().split())
    out = run(x)
    if D > T * S:
        assert out != 'Yes\n', f'Should not output Yes when D > T*S'

def test_exact_output_no_extra(run, x):
    out = run(x)
    # Already checked format, but ensure no leading/trailing spaces
    assert out == 'Yes\n' or out == 'No\n', f'Output must be exactly Yes or No with newline'

