tests_src:
def test_output_shape(run, x):
    out = run(x)
    assert out in ('AC\n', 'WA\n'), f'output must be AC or WA with newline, got {repr(out)}'

def test_ac_implies_first_A(run, x):
    out = run(x)
    if out == 'AC\n':
        assert x[0] == 'A', f'AC output but first char is {x[0]}'

def test_ac_implies_one_C_in_range(run, x):
    out = run(x)
    if out == 'AC\n':
        s = x.strip()
        n = len(s)
        # positions 2 to n-2 inclusive (0-indexed)
        c_count = sum(1 for i in range(2, n-1) if s[i] == 'C')
        assert c_count == 1, f'AC output but C count in range is {c_count}'

def test_ac_implies_others_lowercase(run, x):
    out = run(x)
    if out == 'AC\n':
        s = x.strip()
        n = len(s)
        # find the C in range
        c_pos = -1
        for i in range(2, n-1):
            if s[i] == 'C':
                c_pos = i
                break
        # all chars except first and c_pos must be lowercase
        for i, ch in enumerate(s):
            if i == 0 or i == c_pos:
                continue
            assert ch.islower(), f'AC output but char at {i} is uppercase: {ch}'

def test_wa_implies_violation(run, x):
    out = run(x)
    if out == 'WA\n':
        s = x.strip()
        n = len(s)
        # check conditions
        cond1 = s[0] == 'A'
        cond2 = sum(1 for i in range(2, n-1) if s[i] == 'C') == 1
        cond3 = True
        c_pos = -1
        for i in range(2, n-1):
            if s[i] == 'C':
                c_pos = i
        for i, ch in enumerate(s):
            if i == 0 or i == c_pos:
                continue
            if not ch.islower():
                cond3 = False
                break
        # if all three hold, output should have been AC
        if cond1 and cond2 and cond3:
            assert False, 'WA output but all conditions satisfied'

def test_metamorphic_swap_lowercase(run, x):
    # Only if input is AC, create a modified still valid AC string
    out = run(x)
    if out == 'AC\n':
        s = x.strip()
        n = len(s)
        # find two lowercase positions not first, not C
        lower_pos = [i for i in range(1, n) if s[i].islower()]
        if len(lower_pos) >= 2:
            # swap two lowercase letters
            i, j = lower_pos[0], lower_pos[1]
            lst = list(s)
            lst[i], lst[j] = lst[j], lst[i]
            s2 = ''.join(lst) + '\n'
            # modified string still satisfies conditions (swapping lowercase doesn't affect)
            # run on modified
            out2 = run(s2)
            assert out2 == 'AC\n', f'Swapping lowercase letters changed output from AC to {out2}'

def test_count_uppercase_exact(run, x):
    out = run(x)
    if out == 'AC\n':
        s = x.strip()
        uppercase = [ch for ch in s if ch.isupper()]
        assert len(uppercase) == 2, f'AC output but uppercase count is {len(uppercase)}'
        assert uppercase[0] == 'A' and uppercase[1] == 'C', f'AC output but uppercase letters are {uppercase}'

def test_C_position_range(run, x):
    out = run(x)
    if out == 'AC\n':
        s = x.strip()
        n = len(s)
        c_pos = s.find('C')
        # C must be between index 2 and n-2 inclusive
        assert 2 <= c_pos <= n-2, f'AC output but C at position {c_pos}'

def test_lowercase_all_except_two(run, x):
    out = run(x)
    if out == 'AC\n':
        s = x.strip()
        # make a copy where we lower the first and the C
        lst = list(s)
        lst[0] = 'a'
        for i in range(2, len(s)-1):
            if s[i] == 'C':
                lst[i] = 'c'
                break
        # now all should be lowercase
        for ch in lst:
            assert ch.islower(), f'AC output but after lowering A and C, still uppercase: {ch}'

def test_consistency_with_casefold(run, x):
    out = run(x)
    if out == 'AC\n':
        s = x.strip()
        # after first char, replace 'C' with 'c', then all must be lower
        part = s[1:].replace('C', 'c')
        for ch in part:
            assert ch.islower(), f'AC output but after replacing C, found uppercase: {ch}'

def test_output_format(run, x):
    out = run(x)
    assert out in ('AC\n', 'WA\n'), f'Invalid output: {repr(out)}'

def test_ac_first_A(run, x):
    out = run(x)
    if out == 'AC\n':
        s = x.strip()
        assert s[0] == 'A', f'First character not A: {s}'

def test_ac_one_C_in_range(run, x):
    out = run(x)
    if out == 'AC\n':
        s = x.strip()
        # range indices 2 to len(s)-2 inclusive
        c_count = s[2:-1].count('C')
        assert c_count == 1, f'Expected exactly one C in range, got {c_count}'

def test_ac_others_lowercase(run, x):
    out = run(x)
    if out == 'AC\n':
        s = x.strip()
        # find the C in range
        c_pos = -1
        for i in range(2, len(s)-1):  # because slice s[2:-1] corresponds to indices 2..len(s)-2
            if s[i] == 'C':
                if c_pos != -1:
                    # more than one, but already checked in previous test
                    pass
                c_pos = i
        # now check all chars except index 0 and c_pos are lowercase
        for i, ch in enumerate(s):
            if i == 0 or i == c_pos:
                continue
            if not ('a' <= ch <= 'z'):
                assert False, f'Uppercase letter at index {i}: {ch}'

def test_wa_implies_failure(run, x):
    out = run(x)
    if out == 'WA\n':
        s = x.strip()
        cond1 = s[0] == 'A'
        cond2 = s[2:-1].count('C') == 1
        # cond3: all other letters lowercase
        # compute by removing first char and the one C in range if cond2 holds
        ok = True
        if cond1 and cond2:
            # find the C position
            c_pos = -1
            for i in range(2, len(s)-1):
                if s[i] == 'C':
                    c_pos = i
                    break
            for i, ch in enumerate(s):
                if i == 0 or i == c_pos:
                    continue
                if not ('a' <= ch <= 'z'):
                    ok = False
                    break
        else:
            ok = False
        # if all three conditions hold, then output should have been AC
        # so we assert that not all hold
        assert not (cond1 and cond2 and ok), f'All conditions satisfied but output WA: {s}'

def test_metamorphic_uppercase_flip(run, x):
    out = run(x)
    if out == 'AC\n':
        s = x.strip()
        # find a character that is lowercase and not the first A nor the C in range
