def test_full_verification(run, x):
    out = run(x)
    s = x.strip()
    # correct checker based on spec
    if not (4 <= len(s) <= 10):
        expected = 'WA'
    else:
        cond1 = s[0] == 'A'
        cond2 = s[2:-1].count('C') == 1
        cond3 = True
        if cond1 and cond2:
            # find the C position
            c_pos = -1
            for i in range(2, len(s)-1):
