                if not ('a' <= ch <= 'z'):
                    cond3 = False
                    break
        else:
            cond3 = False
        expected = 'AC' if (cond1 and cond2 and cond3) else 'WA'
    assert out.strip() == expected, f'Verification mismatch: output {out.strip()}, expected {expected}'

