def test_non_negative(run, x):
    out = run(x).strip()
    assert out != ''
    val = int(out)
    assert val >= 0

def test_exists_pair_with_difference(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    A = list(map(int, lines[1].split()))
    out = int(run(x).strip())
    found = False
    for i in range(len(A)):
        for j in range(len(A)):
            if i != j and abs(A[i] - A[j]) == out:
                found = True
    assert found

def test_upper_bound_max_minus_min(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    A = list(map(int, lines[1].split()))
    out = int(run(x).strip())
    assert out <= max(A) - min(A)

def test_lower_bound_max_minus_min_if_not_all_equal(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    A = list(map(int, lines[1].split()))
    out = int(run(x).strip())
    if max(A) != min(A):
        # correct answer must be max(A)-min(A)
        assert out == max(A) - min(A)

def test_zero_iff_all_equal(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    A = list(map(int, lines[1].split()))
    out = int(run(x).strip())
    all_equal = all(x == A[0] for x in A)
    if out == 0:
        assert all_equal
    else:
        assert not all_equal

def test_invariant_under_reversal(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    N = lines[0].strip()
    A = lines[1].strip()
    rev_input = N + '\n' + ' '.join(A.split()[::-1])
    out1 = int(run(x).strip())
    out2 = int(run(rev_input).strip())
    assert out1 == out2

def test_invariant_under_adding_constant(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    N = int(lines[0].strip())
    A = list(map(int, lines[1].split()))
    # add a constant (e.g., 100) to all elements
    constant = 100
    new_A = [str(a + constant) for a in A]
    new_input = str(N) + '\n' + ' '.join(new_A)
    out1 = int(run(x).strip())
    out2 = int(run(new_input).strip())
    assert out1 == out2

def test_output_integer_format(run, x):
    out = run(x).strip()
    # must be a single integer, possibly with newline
    int(out)  # raises if not integer

def test_answer_is_at_least_any_pair_difference(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    A = list(map(int, lines[1].split()))
    out = int(run(x).strip())
    # For any two distinct indices, output >= |A[i]-A[j]|
    # We'll check a few random pairs; but for safety check all (N <= 100, so at most 10000 pairs)
    for i in range(len(A)):
        for j in range(len(A)):
            if i != j:
                assert out >= abs(A[i] - A[j])

def test_answer_equals_max_minus_min_unless_all_equal(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    A = list(map(int, lines[1].split()))
    out = int(run(x).strip())
    if len(set(A)) == 1:
        assert out == 0
    else:
        assert out == max(A) - min(A)

