def test_YYMM_implies_last_two_is_month(run, x):
    out = run(x).strip()
    if out == "YYMM":
        s2 = int(x.strip()[2:])
        assert 1 <= s2 <= 12, f"YYMM output but last two {s2} not a valid month"

def test_MMYY_implies_first_two_is_month(run, x):
    out = run(x).strip()
    if out == "MMYY":
        s1 = int(x.strip()[:2])
        assert 1 <= s1 <= 12, f"MMYY output but first two {s1} not a valid month"

def test_AMBIGUOUS_implies_both_months(run, x):
    out = run(x).strip()
    if out == "AMBIGUOUS":
        s1 = int(x.strip()[:2])
        s2 = int(x.strip()[2:])
        assert 1 <= s1 <= 12 and 1 <= s2 <= 12, f"AMBIGUOUS output but parts not both months"

def test_NA_implies_neither_month(run, x):
    out = run(x).strip()
    if out == "NA":
        s1 = int(x.strip()[:2])
        s2 = int(x.strip()[2:])
        assert not (1 <= s1 <= 12) and not (1 <= s2 <= 12), f"NA output but at least one part is a month"

def test_swap_halves_swaps_YYMM_MMYY(run, x):
    s = x.strip()
    swapped = s[2:] + s[:2]
    out1 = run(x).strip()
    out2 = run(swapped + "\n").strip()
    if out1 == "YYMM":
        assert out2 == "MMYY", f"Swapped input should change YYMM to MMYY"
    elif out1 == "MMYY":
        assert out2 == "YYMM", f"Swapped input should change MMYY to YYMM"
    elif out1 == "AMBIGUOUS":
        assert out2 == "AMBIGUOUS", f"AMBIGUOUS should stay AMBIGUOUS when swapped"
    elif out1 == "NA":
        assert out2 == "NA", f"NA should stay NA when swapped"

def test_symmetric_input_not_YYMM_or_MMYY(run, x):
    s = x.strip()
    if s[:2] == s[2:]:
        out = run(x).strip()
        assert out in ("AMBIGUOUS", "NA"), f"Symmetric input {s} should not be YYMM or MMYY"

def test_both_months_not_NA(run, x):
    s = x.strip()
    s1 = int(s[:2])
    s2 = int(s[2:])
    if 1 <= s1 <= 12 and 1 <= s2 <= 12:
        out = run(x).strip()
        assert out != "NA", f"Both parts are months, output cannot be NA"

def test_neither_month_is_NA(run, x):
    s = x.strip()
    s1 = int(s[:2])
    s2 = int(s[2:])
    if not (1 <= s1 <= 12) and not (1 <= s2 <= 12):
        out = run(x).strip()
        assert out == "NA", f"Neither part is a month, output must be NA"

def test_exactly_one_month_not_AMBIGUOUS_or_NA(run, x):
    s = x.strip()
    s1 = int(s[:2])
    s2 = int(s[2:])
    month1 = 1 <= s1 <= 12
