tests_src:
def test_max_consecutive(run, x):
    # Certificate: compute actual max consecutive 'R's in input string
    s = x.strip('"')
    # Remove newline if present (inputs are given as strings like "RQR\n")
    if s.endswith('\n'):
        s = s[:-1]
    max_len = 0
    curr = 0
    for ch in s:
        if ch == 'R':
            curr += 1
            max_len = max(max_len, curr)
        else:
            curr = 0
    expected = str(max_len)
    output = run(x).strip()
    assert output == expected, f'Expected {expected}, got {output}'

def test_bounds(run, x):
    # Boundedness: answer between 0 and 3 inclusive
    output = run(x).strip()
    val = int(output)
    assert 0 <= val <= 3

def test_integer(run, x):
    # Invariant: output must be a valid integer
    output = run(x).strip()
    int(output)  # will raise ValueError if not

def test_all_rainy_gives_three(run, x):
    # Certificate: if string is 'RRR', answer must be 3
    s = x.strip('"')
    if s.endswith('\n'):
        s = s[:-1]
    if s == 'RRR':
        output = run(x).strip()
        assert output == '3'

def test_no_rainy_gives_zero(run, x):
    # Certificate: if string contains no 'R', answer must be 0
    s = x.strip('"')
    if s.endswith('\n'):
        s = s[:-1]
    if 'R' not in s:
        output = run(x).strip()
        assert output == '0'

def test_reverse_invariant(run, x):
    # Metamorphic: reversing the string does not change max consecutive rainy days
    s = x.strip('"')
    if s.endswith('\n'):
        s = s[:-1]
    # Only valid if s consists only of 'R' and 'S'
    if all(ch in 'RS' for ch in s):
        rev = s[::-1]
        # Build new input with same format
        new_input = rev + '\n' if s.endswith('\n') else rev
        out1 = run(x).strip()
        out2 = run(new_input).strip()
        assert out1 == out2

def test_at_least_one_consecutive(run, x):
    # Certificate: if there is at least one 'R', answer must be at least 1
    s = x.strip('"')
    if s.endswith('\n'):
        s = s[:-1]
    if 'R' in s:
        output = int(run(x).strip())
        assert output >= 1

def test_all_sunny_zero(run, x):
    # Certificate: if string is 'SSS', answer must be 0
    s = x.strip('"')
    if s.endswith('\n'):
        s = s[:-1]
    if s == 'SSS':
        output = run(x).strip()
        assert output == '0'

def test_three_consecutive_possible(run, x):
    # Boundedness: if there are three 'R's consecutively, answer must be 3
    s = x.strip('"')
    if s.endswith('\n'):
        s = s[:-1]
    if s == 'RRR':
        output = run(x).strip()
        assert output == '3'

def test_output_in_set(run, x):
    # Invariant: output must be one of {0,1,2,3}
    output = run(x).strip()
    val = int(output)
    assert val in {0,1,2,3}

