        if m in reachable:
            assert False, 'NO returned but path exists (BFS found)'

def test_order_invariant(run, x):
    # Since input guarantees a_i non-decreasing, sorting by a_i does nothing
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    teleports = [list(map(int, line.split())) for line in lines[1:]]
    # already sorted, just duplicate
    new_input = f'{n} {m}\n' + '\n'.join(f'{a} {b}' for a,b in teleports)
    out1 = run(x).strip()
    out2 = run(new_input).strip()
    assert out1 == out2, f'Repeating same input should give same output'

def test_algorithm_k_consistency(run, x):
    # compute k as in submitted algorithm
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    teleports = [list(map(int, line.split())) for line in lines[1:]]
    k = 0
    for a,b in teleports:
        if a <= k:
            k = max(k, b)
    out = run(x).strip()
    # if k >= m, answer must be YES; if k < m, answer could be YES or NO (since algorithm may be flawed)
    # but if algorithm says k>=m and answer is NO, that's wrong.
    if k >= m and out != 'YES':
        assert False, f'Algorithm reachable {k} >= {m} but output is {out}'

def test_max_limit_cover(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    teleports = [list(map(int, line.split())) for line in lines[1:]]
    max_b = max(b for _,b in teleports) if teleports else 0
    if max_b >= m and out == 'NO':
        # not sufficient for YES, but check if there is a teleport at 0 that reaches m directly
        direct = any(a==0 and b>=m for a,b in teleports)
        if direct:
            assert False, f'Teleport from 0 to {m} exists but output NO'

