def test_positive_x(run, x):
    out = run(x)
    if out.strip() == '-1':
        return
    nums = list(map(int, out.strip().split()))
    for num in nums:
        assert num >= 1

def test_sum_divisible_by_k(run, x):
    y, k, n = map(int, x.strip().split())
    out = run(x)
    if out.strip() == '-1':
        return
    nums = list(map(int, out.strip().split()))
    for num in nums:
        assert (y + num) % k == 0

def test_sum_leq_n(run, x):
    y, k, n = map(int, x.strip().split())
    out = run(x)
    if out.strip() == '-1':
        return
    nums = list(map(int, out.strip().split()))
    for num in nums:
        assert y + num <= n

def test_x_leq_n_minus_y(run, x):
    y, k, n = map(int, x.strip().split())
    out = run(x)
    if out.strip() == '-1':
        return
    nums = list(map(int, out.strip().split()))
    for num in nums:
        assert num <= n - y

def test_strictly_increasing(run, x):
    out = run(x)
    if out.strip() == '-1':
        return
    nums = list(map(int, out.strip().split()))
    for i in range(1, len(nums)):
        assert nums[i] > nums[i-1]

def test_lower_bound(run, x):
    y, k, n = map(int, x.strip().split())
    out = run(x)
    if out.strip() == '-1':
        # If no solution, verify that no x in [1, n-y] satisfies conditions
        found = False
        for cand in range(1, n - y + 1):
            if (y + cand) % k == 0:
                found = True
                break
        assert not found
    else:
        nums = list(map(int, out.strip().split()))
        # The smallest x should be the smallest positive integer such that (y+x) % k == 0 and x+y ≤ n
        smallest = None
        for cand in range(1, n - y + 1):
            if (y + cand) % k == 0:
                smallest = cand
                break
        if smallest is not None:
            assert nums[0] == smallest

def test_step_k(run, x):
    y, k, n = map(int, x.strip().split())
    out = run(x)
    if out.strip() == '-1':
        return
    nums = list(map(int, out.strip().split()))
    for i in range(1, len(nums)):
        assert nums[i] - nums[i-1] == k

def test_certificate_verification(run, x):
    y, k, n = map(int, x.strip().split())
    out = run(x)
    if out.strip() == '-1':
        # No x exists, verify manually
        exists = any((y + cand) % k == 0 for cand in range(1, n - y + 1))
        assert not exists
    else:
        nums = list(map(int, out.strip().split()))
        for num in nums:
            assert 1 <= num <= n - y
            assert (y + num) % k == 0
        # Also check that no other x in range satisfies conditions and is missing
        # But we only need to verify the given ones are correct; completeness is not required for a certificate.

def test_no_duplicates(run, x):
    out = run(x)
    if out.strip() == '-1':
        return
    nums = list(map(int, out.strip().split()))
    assert len(nums) == len(set(nums))

def test_upper_bound_respected(run, x):
    y, k, n = map(int, x.strip().split())
    out = run(x)
    if out.strip() == '-1':
        return
    nums = list(map(int, out.strip().split()))
    # The largest x should be ≤ n - y and the largest multiple of k - y within that bound.
    # We don't compute the exact largest, but ensure none exceeds n-y.
    for num in nums:
        assert num <= n - y

