def test_bound_upper(run, x):
    MOD = 10**9 + 7
    n, k = map(int, x.strip().split())
    ans = int(run(x).strip())
    # total matrices without constraints: k^(n^2)
    # Since valid matrices are a subset, answer <= k^(n^2) mod MOD
    # Compute k^(n^2) % MOD using pow
    total = pow(k, n*n, MOD)
    assert 0 <= ans <= total


