def test_small_brute(run, x):
    import itertools
    MOD = 10**9 + 7
    n, k = map(int, x.strip().split())
    if n > 3 or k > 3:
        return  # skip large cases
    # brute force all matrices
    total = 0
    for flat in itertools.product(range(1, k+1), repeat=n*n):
        mat = [list(flat[i*n:(i+1)*n]) for i in range(n)]
        ok = True
        for i in range(n):
            if min(mat[i]) != 1:
                ok = False
                break
        if not ok:
            continue
        for j in range(n):
            if min(mat[i][j] for i in range(n)) != 1:
                ok = False
                break
        if ok:
            total += 1
    total %= MOD
    ans = int(run(x).strip())
    assert ans == total


def test_correct_formula_small(run, x):
    MOD = 10**9 + 7
    n, k = map(int, x.strip().split())
    if n > 6 or k > 6:
        return  # skip large cases
    # correct inclusion-exclusion formula
    # answer = sum_{r=0}^n sum_{c=0}^n (-1)^{r+c} C(n,r) C(n,c) (k-1)^{r*c} * k^{n*n - r*c}
    def comb(nn, rr):
        if rr < 0 or rr > nn:
            return 0
        res = 1
        for i in range(1, rr+1):
            res = res * (nn - i + 1) // i
        return res
    ans_correct = 0
    for r in range(n+1):
        for c in range(n+1):
            sign = 1 if ((r+c) % 2 == 0) else -1
            term = comb(n, r) * comb(n, c) % MOD
            term = term * pow(k-1, r*c, MOD) % MOD
            term = term * pow(k, n*n - r*c, MOD) % MOD
            ans_correct = (ans_correct + sign * term) % MOD
    ans_correct %= MOD
    ans = int(run(x).strip())
    assert ans == ans_correct


